begin;
set local statement_timeout='30s';
create temporary table integration_platform_results(label text);
grant select,insert on integration_platform_results to authenticated,service_role;
do $$declare a uuid:=gen_random_uuid();b uuid:=gen_random_uuid();wa uuid;wb uuid;ca uuid:=gen_random_uuid();cb uuid:=gen_random_uuid();r jsonb;cmd uuid;corr uuid:=gen_random_uuid();lease uuid;refresh uuid;h text:=repeat('a',64);j uuid;unrelated uuid;sync_job uuid;sync_lease uuid:=gen_random_uuid();
begin
 insert into auth.users(id,email) values(a,'integration-a@example.invalid'),(b,'integration-b@example.invalid');
 perform set_config('request.jwt.claim.sub',a::text,true);perform set_config('request.jwt.claims',jsonb_build_object('sub',a,'role','authenticated')::text,true);
 wa:=public.create_workspace('Integration A fixture');
 perform set_config('request.jwt.claim.sub',b::text,true);perform set_config('request.jwt.claims',jsonb_build_object('sub',b,'role','authenticated')::text,true);
 wb:=public.create_workspace('Integration B fixture');
 execute 'set local role service_role';
 r:=public.integration_runtime(wa,a,'oauth_begin',jsonb_build_object('connection_id',ca,'provider','google','hashed_state',h,'encrypted_verifier','test-cipher','scopes',jsonb_build_array('scope'),'integrations',jsonb_build_array('gmail')));
 begin perform public.integration_runtime(wa,b,'oauth_consume',jsonb_build_object('hashed_state',h,'provider','google'));raise exception 'Wrong user accepted';exception when insufficient_privilege then null;end;
 begin perform public.integration_runtime(wb,b,'oauth_consume',jsonb_build_object('hashed_state',h,'provider','google'));raise exception 'Wrong tenant accepted';exception when insufficient_privilege then null;end;
 begin perform public.integration_runtime(wa,a,'oauth_consume',jsonb_build_object('hashed_state',h,'provider','microsoft'));raise exception 'Wrong provider accepted';exception when insufficient_privilege then null;end;
 r:=public.integration_runtime(wa,a,'oauth_consume',jsonb_build_object('hashed_state',h,'provider','google'));
 begin perform public.integration_runtime(wa,a,'oauth_consume',jsonb_build_object('hashed_state',h,'provider','google'));raise exception 'OAuth replay accepted';exception when insufficient_privilege then null;end;
 r:=public.integration_runtime(wa,a,'save_grant',jsonb_build_object('connection_id',ca,'hashed_state',h,'external_account_id','account-a','external_account_name','Fixture A','email','a@example.invalid','encrypted_credentials','test-cipher','scopes',jsonb_build_array('scope')));
 if r ? 'encrypted_credentials' or r ? 'credential_revision' then raise exception 'Grant returned vault material';end if;
 insert into integration_platform_results values('OAuth user/workspace/provider binding and one-time state');
 r:=public.integration_runtime(wb,b,'oauth_begin',jsonb_build_object('connection_id',cb,'provider','google','hashed_state',repeat('b',64),'encrypted_verifier','test-cipher','scopes',jsonb_build_array('scope'),'integrations',jsonb_build_array('gmail')));
 execute 'reset role';update relay_private.integration_oauth_states set expires_at=now()-interval '1 minute' where connection_id=cb;execute 'set local role service_role';
 begin perform public.integration_runtime(wb,b,'oauth_consume',jsonb_build_object('hashed_state',repeat('b',64),'provider','google'));raise exception 'Expired state accepted';exception when insufficient_privilege then null;end;
 begin perform public.integration_runtime(wb,b,'load',jsonb_build_object('connection_id',ca));raise exception 'Tenant B loaded A';exception when insufficient_privilege then null;end;
 begin perform public.integration_runtime(wb,b,'disconnect_start',jsonb_build_object('connection_id',ca));raise exception 'Tenant B disconnected A';exception when insufficient_privilege then null;end;
 r:=public.integration_runtime(wa,a,'refresh_claim',jsonb_build_object('connection_id',ca,'revision',2));refresh:=(r#>>'{}')::uuid;
 if refresh is null or public.integration_runtime(wa,a,'refresh_claim',jsonb_build_object('connection_id',ca,'revision',2)) is not null then raise exception 'Concurrent refresh accepted';end if;
 begin perform public.integration_runtime(wa,a,'refresh_finish',jsonb_build_object('connection_id',ca,'revision',1,'lease',refresh,'encrypted_credentials','new-test-cipher','scopes',jsonb_build_array('scope')));raise exception 'Stale refresh accepted';exception when serialization_failure then null;end;
 perform public.integration_runtime(wa,a,'refresh_release',jsonb_build_object('connection_id',ca,'lease',refresh));
 insert into integration_platform_results values('Expiry, tenant isolation and refresh fencing');
 perform set_config('request.jwt.claim.sub',a::text,true);perform set_config('request.jwt.claims',jsonb_build_object('sub',a,'role','authenticated')::text,true);
 execute 'set local role authenticated';
 begin perform public.integration_runtime(wa,a,'load',jsonb_build_object('connection_id',ca));raise exception 'Browser called privileged gateway';exception when insufficient_privilege then null;end;
 begin execute 'select encrypted_credentials from relay_private.integration_connections';raise exception 'Browser read private vault';exception when insufficient_privilege then null;end;
 r:=public.integration_management(wa,'list');if jsonb_array_length(r)<>1 or r->0 ? 'encrypted_credentials' then raise exception 'Metadata projection failed';end if;
 begin perform public.integration_management(wb,'list');raise exception 'Browser read other tenant';exception when insufficient_privilege then null;end;
 perform public.integration_management(wa,'policy_save','{"integration":"gmail","read":true,"create":true,"update":false,"send":true,"delete":false}');
 execute 'set local role service_role';
 r:=public.integration_runtime(wa,a,'command_create',jsonb_build_object('connection_id',ca,'generation',1,'source','agent','action','gmail.send','integration','gmail','verb','send','request_hash',repeat('c',64),'encrypted_input','fixture','risk',2,'confirmation',true,'correlation_id',corr));cmd:=(r->>'id')::uuid;
 begin perform public.integration_runtime(wa,a,'command_claim',jsonb_build_object('connection_id',ca,'generation',1,'command_id',cmd,'request_hash',repeat('c',64)));raise exception 'Unconfirmed action dispatched';exception when insufficient_privilege then null;end;
 execute 'set local role authenticated';perform public.integration_management(wa,'approve',jsonb_build_object('command_id',cmd));
 perform public.integration_management(wa,'policy_save','{"integration":"gmail","read":true,"create":true,"update":false,"send":false,"delete":false}');
 execute 'set local role service_role';
 begin perform public.integration_runtime(wa,a,'command_claim',jsonb_build_object('connection_id',ca,'generation',1,'command_id',cmd,'request_hash',repeat('c',64)));raise exception 'Revoked agent permission dispatched';exception when insufficient_privilege then null;end;
 execute 'set local role authenticated';perform public.integration_management(wa,'policy_save','{"integration":"gmail","read":true,"create":true,"update":false,"send":true,"delete":false}');execute 'set local role service_role';
 begin perform public.integration_runtime(wa,a,'command_claim',jsonb_build_object('connection_id',ca,'generation',1,'command_id',cmd,'request_hash',repeat('d',64)));raise exception 'Changed confirmation payload dispatched';exception when insufficient_privilege then null;end;
 r:=public.integration_runtime(wa,a,'command_claim',jsonb_build_object('connection_id',ca,'generation',1,'command_id',cmd,'request_hash',repeat('c',64)));lease:=(r->>'lease')::uuid;
 begin perform public.integration_runtime(wa,a,'command_claim',jsonb_build_object('connection_id',ca,'generation',1,'command_id',cmd,'request_hash',repeat('c',64)));raise exception 'Action dispatched twice';exception when insufficient_privilege then null;end;
 perform public.integration_runtime(wa,a,'command_finish',jsonb_build_object('connection_id',ca,'generation',1,'command_id',cmd,'lease',lease,'status','succeeded','encrypted_result','fixture-result'));
 insert into integration_platform_results values('Private schema/grants, exact confirmation, revoked policy and single dispatch');
 perform public.integration_runtime(wa,a,'sync_configure',jsonb_build_object('connection_id',ca,'generation',1,'resource','calendar:owner@example.com','enabled',true));
 r:=public.integration_runtime(wa,a,'sync_enqueue',jsonb_build_object('connection_id',ca,'generation',1,'resource','calendar:owner@example.com'));sync_job:=(r->>'job_id')::uuid;
 r:=public.integration_runtime(wa,a,'sync_enqueue',jsonb_build_object('connection_id',ca,'generation',1,'resource','calendar:owner@example.com'));if (r->>'job_id')::uuid<>sync_job then raise exception 'Queued sync not coalesced';end if;
 execute 'reset role';update relay_private.jobs set status='running',lease=sync_lease,leased_until=now()+interval '3 minutes' where id=sync_job;execute 'set local role service_role';
 begin perform public.integration_runtime(wa,a,'sync_commit',jsonb_build_object('connection_id',ca,'generation',1,'job_id',sync_job,'job_lease',gen_random_uuid(),'resource','calendar:owner@example.com','revision',0,'encrypted_cursor','fixture','objects','[]'::jsonb));raise exception 'Stale worker committed sync';exception when serialization_failure then null;end;
 perform public.integration_runtime(wa,a,'sync_commit',jsonb_build_object('connection_id',ca,'generation',1,'job_id',sync_job,'job_lease',sync_lease,'resource','calendar:owner@example.com','revision',0,'encrypted_cursor','fixture','objects',jsonb_build_array(jsonb_build_object('external_id','event-1','encrypted_metadata','fixture','deleted',false,'remote_updated_at','2026-10-10T12:00:00Z'))));
 begin perform public.integration_runtime(wa,a,'sync_commit',jsonb_build_object('connection_id',ca,'generation',1,'job_id',sync_job,'job_lease',sync_lease,'resource','calendar:owner@example.com','revision',0,'encrypted_cursor','fixture','objects','[]'::jsonb));raise exception 'Stale cursor committed sync';exception when serialization_failure then null;end;
 execute 'reset role';update relay_private.jobs set status='completed',lease=null,leased_until=null where id=sync_job;execute 'set local role service_role';
 r:=public.integration_runtime(wa,a,'sync_enqueue',jsonb_build_object('connection_id',ca,'generation',1,'resource','calendar:owner@example.com'));if (r->>'job_id')::uuid=sync_job then raise exception 'Completed job swallowed new notification';end if;
 insert into integration_platform_results values('Calendar email IDs, cursor/worker fencing, coalescing and notifications after completed sync');
 r:=public.integration_runtime(wa,a,'admit',jsonb_build_object('connection_id',ca));if not (r->>'allowed')::boolean then raise exception 'Normal admission failed';end if;
 perform public.integration_runtime(wa,a,'rate_block',jsonb_build_object('connection_id',ca,'seconds',10));r:=public.integration_runtime(wa,a,'admit',jsonb_build_object('connection_id',ca));if (r->>'allowed')::boolean then raise exception 'Provider cooldown bypassed';end if;
 r:=public.integration_runtime(wa,a,'webhook_enqueue',jsonb_build_object('connection_id',ca,'generation',1,'event_id','fixture-event','event_type','mail.changed','encrypted_payload','fixture-cipher'));j:=(r->>'job_id')::uuid;
 r:=public.integration_runtime(wa,a,'webhook_enqueue',jsonb_build_object('connection_id',ca,'generation',1,'event_id','fixture-event','event_type','mail.changed','encrypted_payload','fixture-cipher'));if r->>'duplicate'<>'true' then raise exception 'Webhook replay not deduplicated';end if;
 execute 'reset role';unrelated:=relay_private.put_job(wb,b,'notifications','unrelated-fixture','{}');execute 'set local role service_role';
 perform public.integration_runtime(wa,a,'disconnect_start',jsonb_build_object('connection_id',ca));
 begin perform public.integration_runtime(wa,a,'load',jsonb_build_object('connection_id',ca));raise exception 'Revoked connection loaded';exception when insufficient_privilege then null;end;
 begin perform public.integration_runtime(wa,a,'webhook_enqueue',jsonb_build_object('connection_id',ca,'generation',1,'event_id','late','event_type','mail.changed','encrypted_payload','fixture-cipher'));raise exception 'Revoked webhook accepted';exception when insufficient_privilege then null;end;
 perform public.integration_runtime(wa,a,'disconnect_finish',jsonb_build_object('connection_id',ca));
 execute 'reset role';
 if exists(select 1 from relay_private.integration_connections where id=ca and encrypted_credentials is not null) then raise exception 'Disconnected credentials retained';end if;
 if not exists(select 1 from relay_private.jobs where id=unrelated and status='queued') then raise exception 'Disconnect cancelled another tenant job';end if;
 if exists(select 1 from relay_private.jobs where id=j and status<>'dead') then raise exception 'Disconnected job survived';end if;
 if exists(select 1 from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='relay_private' and c.relname like 'integration_%' and c.relkind='r' and not c.relrowsecurity) then raise exception 'Integration table without RLS';end if;
 insert into integration_platform_results values('Rate cooldown, webhook idempotency, disconnect cancellation and RLS');
 execute 'set local role service_role';
 perform public.integration_runtime(wa,a,'oauth_begin',jsonb_build_object('connection_id',ca,'provider','google','hashed_state',repeat('e',64),'encrypted_verifier','fixture','scopes',jsonb_build_array('scope'),'integrations',jsonb_build_array('gmail')));
 perform public.integration_runtime(wa,a,'oauth_consume',jsonb_build_object('hashed_state',repeat('e',64),'provider','google'));
 perform public.integration_runtime(wa,a,'save_grant',jsonb_build_object('connection_id',ca,'hashed_state',repeat('e',64),'external_account_id','changed-account','external_account_name','Changed fixture','email','changed@example.invalid','encrypted_credentials','fixture','scopes',jsonb_build_array('scope')));
 begin perform public.integration_runtime(wa,a,'webhook_enqueue',jsonb_build_object('connection_id',ca,'generation',1,'event_id','stale-account','event_type','gmail.history','encrypted_payload','fixture'));raise exception 'Old account webhook accepted';exception when insufficient_privilege then null;end;
 begin perform public.integration_runtime(wa,a,'command_create',jsonb_build_object('connection_id',ca,'generation',1,'source','user','action','gmail.send','integration','gmail','verb','send','request_hash',repeat('f',64),'encrypted_input','fixture','risk',2,'confirmation',false,'correlation_id',gen_random_uuid()));raise exception 'Old credentials admitted dispatch';exception when insufficient_privilege then null;end;
 perform public.integration_runtime(wb,b,'oauth_begin',jsonb_build_object('connection_id',cb,'provider','google','hashed_state',repeat('f',64),'encrypted_verifier','fixture','scopes',jsonb_build_array('scope'),'integrations',jsonb_build_array('gmail')));
 perform public.integration_runtime(wb,b,'oauth_consume',jsonb_build_object('hashed_state',repeat('f',64),'provider','google'));
 perform public.integration_runtime(wb,b,'save_grant',jsonb_build_object('connection_id',cb,'hashed_state',repeat('f',64),'external_account_id','account-b','external_account_name','Fixture B','email','b@example.invalid','encrypted_credentials','fixture','scopes',jsonb_build_array('scope')));
 execute 'reset role';update public.memberships set role='viewer' where workspace_id=wb and user_id=b;
 perform relay_private.integration_maintenance();
 if not exists(select 1 from relay_private.integration_connections where id=cb and status='revoked') then raise exception 'Downgraded member grant not revoked';end if;
 if not exists(select 1 from relay_private.jobs where type='integration_revoke' and payload->>'connection_id'=cb::text and status='queued') then raise exception 'Remote revocation not queued';end if;
 execute 'set local role service_role';perform public.integration_runtime(wb,b,'revoke_load',jsonb_build_object('connection_id',cb));perform public.integration_runtime(wb,b,'disconnect_finish',jsonb_build_object('connection_id',cb));execute 'reset role';
 insert into integration_platform_results values('Changed-account webhook/action fencing and removed/downgraded member remote revocation');
end $$;
select label,'PASS' result from integration_platform_results;
rollback;
